import type { ReviewRow } from "./clean.ts";

/**
 * Renders the human review checklist as Markdown.
 * The output is generated, so approvals happen in corrections.ts, not here.
 */
export const renderReview = (rows: ReviewRow[]): string => {
  const pending = rows.filter((r) => r.status === "pending").length;
  const applied = rows.length - pending;

  const lines = [
    "# Data Corrections Review",
    "",
    "_Generated by `npm run data:clean`. Do not edit by hand._",
    "",
    "Every field that differs between `italy.json` and `src/data/italy-clean.json`.",
    "To approve an AI draft, set `approved: true` on it in `src/data/corrections.ts`, then re-run the script.",
    "",
    rows.length === 0
      ? "No changes."
      : `${rows.length} changes: ${applied} applied, ${pending} pending approval.`,
    "",
  ];

  if (rows.length > 0) {
    lines.push(
      "| id | Place | Field | From | To | Reason | Source | Status |",
      "|---|---|---|---|---|---|---|---|",
      ...rows.map(
        (r) =>
          `| ${r.placeId} | ${cell(r.placeName)} | ${r.field} | ${value(r.from)} | ${value(r.to)} | ${cell(r.reason)} | ${r.source} | ${r.status === "applied" ? "✅ applied" : "⏳ pending"} |`,
      ),
      "",
    );
  }

  return lines.join("\n");
};

const value = (v: unknown): string => "`" + cell(JSON.stringify(v)) + "`";

const cell = (text: string): string => text.replaceAll("|", "\\|");
